    this.resetRelicBannerForLevel();
    this.submarine = null;
    this.coralBarriers = [];
    this.rescueBubbles = [];
    this.jellyfish = [];
    this.subTorpedoes = [];
    this.subKelp = [];
    this.subAmbientBubbles = null;
    this.subAmbientBubbleData = null;
    this.subJellyKit = null;
    this.subJellySpawnTimer = 0;
    this.subJellySeq = 0;
    this.subBubblesPopped = 0;
